```js
function killLeftoverServeProcesses() {
  const result = dockerExec(`ps 2>/dev/null | grep -F '${REMOTE_DIR}/serve.sh' | grep -v grep || true`)
  const lines = result.stdout.trim().split('\n').filter(Boolean)
