function printTimeline(result) {
  console.log(`  请求：${result.url}`)
  console.log(`  HTTP ${result.status}，Content-Type: ${result.contentType || '(无)'}，首个响应体块：${fmt(result.firstChunkAt)}`)
  console.log('  帧时间线：')
  if (!result.frames.length) { console.log('    （未收到 data 帧）'); return }
