function buildCheckConfig(source) {
  let config = source
  let wrapped = false
  if (!/^\s*http\s*\{/m.test(config)) {
    config = `worker_processes 1;\nevents {\n    worker_connections 128;\n}\nhttp {\n    include /etc/nginx/mime.types;\n    default_type application/octet-stream;\n\n${indent(config, 4)}\n}\n`
    wrapped = true
  }
  let upstreamInjected = false
  if (!/upstream\s+agent-hub-backend\s*\{/.test(config)) {
    config = config.replace(/http\s*\{/, `http {\n    upstream agent-hub-backend {\n        server 127.0.0.1:8000;\n        keepalive 32;\n    }\n`)
    upstreamInjected = true
  }
