  const rootReplaced = rootRe.test(config)
  if (rootReplaced) {
    config = config.replace(rootRe, `$1root ${htmlDir};`)
  } else {
    // 在第一个 server { 后插入 root
    config = config.replace(/server\s*\{/, `server {\n        root ${htmlDir};`)
  }
  return { config, wrapped, upstreamInjected, rootReplaced }
}
```
