}

function writeRemoteFile(path, content, mode = '644') {
  const result = dockerExec(`cat > '${path}' && chmod ${mode} '${path}'`, { input: content })
  if (result.status !== 0) {
    fail(`写入容器文件失败 ${path}：${(result.stderr || result.stdout).trim()}`)
