  log(`  - ${wrapped ? '检测到 server 片段，已补 events/http 外壳' : '已是完整 nginx.conf（含 events/http）'}`)
  log(
    `  - ${
      upstreamInjected
        ? '缺少 upstream agent-hub-backend，已补 server 127.0.0.1:8000'
        : 'upstream agent-hub-backend 已存在（保留原地址）'
    }`,
  )
