async function collectFrames(pathname, label) {
  const url = `http://127.0.0.1:${state.hostPort}${pathname}`
  console.log(`\n==> 采集 ${label}：${url}`)
  const startedAt = performance.now()
  let response
  try {
    response = await fetch(url, {
      headers: { Accept: 'text/event-stream', 'Cache-Control': 'no-cache' },
      cache: 'no-store',
      signal: AbortSignal.timeout(20_000),
    })
  } catch (error) {
    fail(`请求 ${url} 失败：${error.message}\n提示：脚本已设置 NO_PROXY=*；请确认 ${CONTAINER} 的 80 端口映射到宿主 ${state.hostPort}。`)
  }
  if (!response.ok) fail(`请求 ${url} 返回 HTTP ${response.status}`)
  const contentType = response.headers.get('content-type') || ''
  if (!response.body) fail(`请求 ${url} 没有响应体`)
  const reader = response.body.getReader()
  const decoder = new TextDecoder()
  let buffer = ''
  let firstChunkAt = null
  let byteCount = 0
  const frames = []
  try {
    while (frames.length < FRAME_COUNT) {
      const { value, done } = await reader.read()
      if (done) break
      if (firstChunkAt === null) firstChunkAt = performance.now() - startedAt
      byteCount += value.byteLength
      buffer += decoder.decode(value, { stream: true })
      let boundary = buffer.indexOf('\n\n')
      while (boundary !== -1) {
        const rawEvent = buffer.slice(0, boundary)
        buffer = buffer.slice(boundary + 2)
        const dataLines = rawEvent
          .split(/\r?\n/)
          .filter((line) => line.startsWith('data:'))
          .map((line) => line.slice(5).trimStart())
        if (dataLines.length > 0) {
          frames.push({ t: performance.now() - startedAt, data: dataLines.join('\n') })
        }
        boundary = buffer.indexOf('\n\n')
      }
    }
  } finally {
    try { await reader.cancel() } catch { /* 关闭失败不影响计时结果 */ }
  }
  return { url, status: response.status, contentType, firstChunkAt, byteCount, frames, elapsed: performance.now() - startedAt }
}
```
